// actor/scripts/peek.ts — print what an actor looks like right now. Usage: bun scripts/peek.ts [actorId]
// Target the deployment with: set -a; source .env.cloud; set +a; bun scripts/peek.ts
import { ACTOR_ID, hhmm } from "../../shared/types"
// @ts-ignore generated by `terse actor generate`
import { actors } from "../generated/index.js"

const dock = actors.Dock.get(process.argv[2] ?? ACTOR_ID)
const s = await dock.snapshot()
console.log(`${hhmm(s.simMin)} (${s.speed}x${s.frozen ? ", frozen" : ""}) seeded=${s.seeded} real=${new Date().toISOString()}`)
console.log("counters:", JSON.stringify(s.counters))
console.log("appts:", s.appts.map((a: any) => `${a.truckId}@${a.door}/${hhmm(a.startMin)}:${a.status}`).join("  "))
console.log("timers:", s.timers.map((t: any) => `${hhmm(t.atMin)} ${t.kind} ${t.truckId ?? t.auctionId ?? t.threadId ?? ""}`).join(" | ") || "none")
console.log("auctions:", s.auctions.map((a: any) => `${a.id} door ${a.door} ${hhmm(a.startMin)} ${a.status} bids=${a.bids.length}`).join(" | ") || "none")
console.log("claims:", JSON.stringify(s.claims))
console.log("last events:")
for (const e of s.events.slice(-10)) console.log(`  ${hhmm(e.atMin)} ${e.kind.padEnd(14)} ${e.detail}`)
